/* Selector: identifies which HTML elements to style */
h1 {
  /* Declaration: property : value; */
  color: #2563eb;          /* Property: color, Value: #2563eb */
  font-size: 2.25rem;      /* Property: font-size, Value: 2.25rem */
  text-align: center;      /* Property: text-align, Value: center */
}

/* 1. Universal Selector: targets every element */
* {
  box-sizing: border-box;
}

/* 2. Element/Type Selector: targets all <p> tags */
p {
  line-height: 1.6;
  margin-bottom: 1rem;
}

/* 3. Class Selector: targets elements with class="featured-card" */
.featured-card {
  background-color: #f8fafc;
  border: 1px solid #e2e8f0;
  padding: 1.5rem;
}

/* 4. ID Selector: targets single unique element with id="main-navigation" */
#main-navigation {
  background-color: #0f172a;
  color: #ffffff;
}

.container {
  /* Percentage: relative to parent width */
  width: 90%;

  /* rem: relative to root (html) font size (typically 16px) */
  max-width: 75rem; /* 75 * 16px = 1200px */
  margin: 0 auto;
  padding: 2rem;
}

.hero-banner {
  /* vh: percentage of viewport height */
  min-height: 70vh;

  /* px: fixed absolute measurement for hair-thin border lines */
  border-bottom: 1px solid #d1d5db;
}

.card-button {
  /* em: relative to the element's own font-size */
  font-size: 1rem;
  padding: 0.5em 1em; /* scales proportionally if font-size changes */
}
